import{c as a,Q as n,j as o,m as s}from"./chunks/framework.t4rEqR7d.js";const u=JSON.parse('{"title":"pagentv4","description":"","frontmatter":{},"headers":[],"relativePath":"pagentv4/index.md","filePath":"pagentv4/index.md"}'),t={name:"pagentv4/index.md"};function l(i,e,d,r,p,c){return n(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="pagentv4" tabindex="-1">pagentv4 <a class="header-anchor" href="#pagentv4" aria-label="Permalink to &quot;pagentv4&quot;">​</a></h1><p>语言：<a href="/pagent/zh/pagentv4/">中文</a> | <a href="/pagent/pagentv4/">English</a></p><p><code>pagentv4</code> is the newer typed API in this repository.</p><p>Use these pages if you want:</p><ul><li><code>Provider</code> instead of <code>LLM</code></li><li><code>Message</code> / <code>Messages</code> instead of <code>Session</code></li><li><code>Runner</code> for thread-based orchestration, persistence, and sandbox workspaces</li><li>A <strong>sandbox</strong> (companion computer) with file and command tools</li><li>Optional <strong>Thread</strong> and <strong>Skill</strong> support for long-lived REPL-style apps</li></ul><h2 id="module-layout" tabindex="-1">Module layout <a class="header-anchor" href="#module-layout" aria-label="Permalink to &quot;Module layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>core/       AgentCore, Message, Provider, Tool, Event</span></span>
<span class="line"><span>ithread/    IThread Protocol + ThreadSpec</span></span>
<span class="line"><span>runtime/    loop_core, LoopAdapter, BaseRunner, Runner, VanillaRunner, Thread</span></span>
<span class="line"><span>conversation/ ConversationStore implementations used through Thread</span></span>
<span class="line"><span>sandbox/    Backend, Sandbox, built-in file/command tools</span></span>
<span class="line"><span>tools/      reusable tool functions</span></span>
<span class="line"><span>adapters/   ACP encode/decode</span></span>
<span class="line"><span>skills/     SKILL.md discovery and on-demand loading</span></span></code></pre></div><p>There are several layers inside <code>runtime/</code>:</p><ul><li><code>loop_core</code> defines the shared run / turn / tool loop semantics</li><li><code>LoopAdapter</code> carries the shared loop skeleton, and each runner layers on capabilities: <ul><li><code>VanillaRunner(LoopAdapter)</code> — minimal in-memory environment</li><li><code>BaseRunner(LoopAdapter)</code> — adds thread, conversation store, sandbox, skills</li><li><code>Runner(BaseRunner)</code> — adds inbound control (steer/cancel/permit) and tool hooks</li></ul></li></ul><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><ul><li><a href="./quick-start.html">Quick start</a></li><li><a href="./core-types.html">Core types</a></li><li><a href="./messages.html">Messages</a></li><li><a href="./tools.html">Tools</a></li><li><a href="/pagent/vscode.html">VS Code extension</a></li><li><a href="./sandbox.html">Sandbox</a></li></ul><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>New work should use <code>pagentv4</code> and <code>app</code> (terminal REPL). The top-level <code>pagent</code> package still documents the older <code>Session + LLM</code> API for now.</p>`,13)])])}const m=a(t,[["render",l]]);export{u as __pageData,m as default};
